recognized_test_commands.command:
/bin/bash -lc "cat > models/trivy_sources_test.go <<'EOF'
package models

import \"testing\"

// Omitting Trivy source keys from aggregation must break this test.
func TestTrivySourceMetadataIsAggregated(t *testing.T) {
 v := VulnInfo{CveContents: CveContents{
  \"trivy:debian\": {{Type: \"trivy:debian\", Title: \"Debian title\", Summary: \"Debian summary\", Cvss3Severity: \"LOW\", Cvss3Score: 3.1, Cvss2Score: 2.5}},
  \"trivy:ubuntu\": {{Type: \"trivy:ubuntu\", Title: \"Ubuntu title\", Summary: \"Ubuntu summary\", Cvss3Severity: \"MEDIUM\", Cvss3Score: 5.2}},
 }}
 if len(v.Titles(\"en\", \"trivy\")) "'!= 2 { t.Errorf("titles: %v", v.Titles("en", "trivy")) }
 if len(v.Summaries("en", "trivy")) != 2 { t.Errorf("summaries: %v", v.Summaries("en", "trivy")) }
 if len(v.Cvss2Scores()) != 1 || v.Cvss2Scores()[0].Value.Score != 2.5 { t.Errorf("CVSS2: %v", v.Cvss2Scores()) }
 scores := v.Cvss3Scores()
 if len(scores) != 2 || scores[0].Value.Score != 3.1 || scores[1].Value.Score != 5.2 { t.Errorf("CVSS3: %v", scores) }
}
EOF
gofmt -w models/trivy_sources_test.go
GOTOOLCHAIN=local GOPROXY=off go test ./models -run TestTrivySourceMetadataIsAggregated -count=1'

/bin/bash -lc "cat >> contrib/trivy/pkg/converter_test.go <<'EOF'

// Assigning the selected vendor severity to a different CVSS source must break this test.
func TestConvertDoesNotMisattributeSelectedSeverity(t *testing.T) {
 results := types.Results{{Vulnerabilities: []types.DetectedVulnerability{{
  VulnerabilityID: \"CVE-2024-0003\", SeveritySource: \"debian\",
  Vulnerability: dbtypes.Vulnerability{Severity: \"LOW\", VendorSeverity: dbtypes.VendorSeverity{\"debian\": dbtypes.SeverityLow}, CVSS: dbtypes.VendorCVSS{\"nvd\": {V3Score: 7.5}}},
 }}}}
 got, err := Convert(results)
 if err "'!= nil { t.Fatal(err) }
 nvd := got.ScannedCves["CVE-2024-0003"].CveContents["trivy:nvd"]
 if len(nvd) != 1 || nvd[0].Cvss3Severity != "" { t.Errorf("NVD content = %+v", nvd) }
}
EOF
gofmt -w contrib/trivy/pkg/converter_test.go
GOTOOLCHAIN=local GOPROXY=off go test ./contrib/trivy/pkg -run TestConvertDoesNotMisattributeSelectedSeverity -count=1'

/bin/bash -lc "cat >> contrib/trivy/pkg/converter_test.go <<'EOF'

